22	/**
23	 * Maps Owner & OwnerDto using Mapstruct
24	 */
25	@Mapper(uses = PetMapper.class)
26	public abstract class OwnerMapper {
27	
28	    /** Used to count the members of an owner's household when deriving derived fields. */
29	    @Autowired
30	    protected ClinicService clinicService;
31	
32	    /** Single source of truth for the city-to-region mapping behind an owner's locality. */
33	    @Autowired
34	    protected CityRegionResolver cityRegionResolver;
35	
36	    /** Formats the stored E.164 telephone into its human-readable display form. */
37	    @Autowired
38	    protected TelephoneNormalizer telephoneNormalizer;
39	
40	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
41	    @Mapping(target = "displayName",
42	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
43	    @Mapping(target = "initials", expression = "java(initials(owner))")
44	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
45	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
46	    @Mapping(target = "locality", expression = "java(locality(owner))")
47	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
48	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
49	    @Mapping(target = "telephoneDisplay", expression = "java(telephoneNormalizer.toDisplayForm(owner.getTelephone()))")
50	    @Mapping(target = "identityKey", expression = "java(identityKey(owner))")
51	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
52	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
53	    public abstract OwnerDto toOwnerDto(Owner owner);
54	
55	    /**
56	     * The owner's age band derived from {@code birthDate} relative to the
57	     * {@code registrationDate}: 'MINOR' when under 18, 'ADULT' from 18 to 64
58	     * inclusive and 'SENIOR' at 65 or older. Returns null when either date is
59	     * absent so no band can be computed.
60	     */
61	    OwnerDto.AgeBandEnum ageBand(Owner owner) {
62	        LocalDate birthDate = owner.getBirthDate();
63	        LocalDate registrationDate = owner.getRegistrationDate();
64	        if (birthDate == null || registrationDate == null) {
65	            return null;
66	        }
67	        int age = Period.between(birthDate, registrationDate).getYears();
68	        if (age < 18) {
69	            return OwnerDto.AgeBandEnum.MINOR;
70	        }
71	        if (age < 65) {
72	            return OwnerDto.AgeBandEnum.ADULT;
73	        }
74	        return OwnerDto.AgeBandEnum.SENIOR;
75	    }
76	
77	    /**
78	     * The owner's check digit: a single Luhn check digit (0-9) computed over the digits
79	     * contained in the customerCode, or null when no customerCode has been assigned.
80	     */
81	    Integer checkDigit(Owner owner) {
82	        String customerCode = owner.getCustomerCode();
83	        return customerCode == null ? null : luhn(customerCode);
84	    }
85	
86	    /**
87	     * The Luhn check digit (0-9) over the digits contained in {@code s}: from the rightmost
88	     * digit leftward, every second digit is doubled (the rightmost first) with digits over 9
89	     * reduced by 9, and the check digit makes the total a multiple of ten.
90	     */
91	    static int luhn(String s) {
92	        int sum = 0;
93	        boolean doubling = true;
94	        for (int i = s.length() - 1; i >= 0; i--) {
95	            char c = s.charAt(i);
96	            if (c < '0' || c > '9') {
97	                continue;
98	            }
99	            int d = c - '0';
100	            if (doubling) {
101	                d *= 2;
102	                if (d > 9) {
103	                    d -= 9;
104	                }
105	            }
106	            sum += d;
107	            doubling = !doubling;
108	        }
109	        return (10 - (sum % 10)) % 10;
110	    }
111	
112	    /**
113	     * The owner's derived identity key: the normalized telephone, the email (or an empty
114	     * string when absent) and the householdId joined by '|'. This single key is the sole
115	     * basis for duplicate detection on create — two owners are duplicates only when their
116	     * whole identityKey matches, so members of one household with different telephones
117	     * (and hence different keys) are all permitted.
118	     */
119	    public static String identityKey(Owner owner) {
120	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
121	        String email = owner.getEmail() == null ? "" : owner.getEmail();
122	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
123	        return telephone + "|" + email + "|" + householdId;
124	    }
125	
126	    /**
127	     * The owner's preferred contact channel: 'EMAIL' when an email address is
128	     * present, otherwise 'PHONE'.
129	     */
130	    String contactPreference(Owner owner) {
131	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
132	        return hasEmail ? "EMAIL" : "PHONE";
133	    }
134	
135	    /**
136	     * The owner's locality: the REGION component of the customerCode identity (the part before
137	     * the first '-' of {@code '<REGION>-<HASH8>'}). When no customerCode has been assigned this
138	     * falls back to the canonical region derived from the owner via {@link CityRegionResolver},
139	     * preferring the postcode over the city, or 'UNKNOWN' when neither yields a known region.
140	     */
141	    String locality(Owner owner) {
142	        String customerCode = owner.getCustomerCode();
143	        if (customerCode != null) {
144	            int dash = customerCode.indexOf('-');
145	            if (dash >= 0) {
146	                return customerCode.substring(0, dash);
147	            }
148	        }
149	        return cityRegionResolver.regionFor(owner.getCity(), owner.getPostcode());
150	    }
151	
152	    /**
153	     * The owner's IANA timezone name derived from the owner's {@link #locality(Owner) locality}
154	     * via the fixed region-to-timezone table (NSW -> Australia/Sydney, VIC -> Australia/Melbourne,
155	     * QLD -> Australia/Brisbane). Returns null when the locality is not a region in the table.
156	     */
157	    String timezone(Owner owner) {
158	        return cityRegionResolver.timezoneForRegion(locality(owner));
159	    }
160	
161	    /**
162	     * The owner's membership points: starting at 0, plus 2 when an email address is present,
163	     * plus 1 when namesakeCount is 0, plus 2 for a household of 3 or more members, plus 3 when
164	     * the owner's tenure is more than 365 days.
165	     */
166	    public int membershipPoints(Owner owner) {
167	        int points = 0;
168	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
169	        if (hasEmail) {
170	            points += 2;
171	        }
172	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
173	        if (uniqueName) {
174	            points += 1;
175	        }
176	        if (householdSize(owner) >= 3) {
177	            points += 2;
178	        }
179	        LocalDate registrationDate = owner.getRegistrationDate();
180	        boolean tenured = registrationDate != null
181	            && ChronoUnit.DAYS.between(registrationDate, LocalDate.now()) > 365;
182	        if (tenured) {
183	            points += 3;
184	        }
185	        return points;
186	    }
187	
188	    /**
189	     * The owner's numeric membership level from 1 to 4, derived from {@link #membershipPoints}:
190	     * level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5 points and level 4 for
191	     * 6 or more points.
192	     */
193	    public int membershipLevel(Owner owner) {
194	        int points = membershipPoints(owner);
195	        if (points >= 6) {
196	            return 4;
197	        }
198	        if (points >= 4) {
199	            return 3;
200	        }
201	        if (points >= 2) {
202	            return 2;
203	        }
204	        return 1;
205	    }
206	
207	    /**
208	     * The number of owners belonging to {@code owner}'s household, i.e. those sharing its
209	     * householdId (including the owner itself once persisted). Returns 0 when the owner has no
210	     * household id assigned.
211	     */
212	    int householdSize(Owner owner) {
213	        String householdId = owner.getHouseholdId();
214	        if (householdId == null) {
215	            return 0;
216	        }
217	        return (int) clinicService.findAllOwners().stream()
218	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
219	            .count();
220	    }
221	
222	    /**
223	     * The owner's salutation: the {@code title} and last name separated by a single space
224	     * (e.g. 'DR who'), or just the last name when no title has been supplied.
225	     */
226	    String salutation(Owner owner) {
227	        String title = owner.getTitle();
228	        if (title == null || title.isBlank()) {
229	            return owner.getLastName();
230	        }
231	        return title + " " + owner.getLastName();
232	    }
233	
234	    /**
235	     * The upper-cased first letters of firstName and lastName, dot-separated with a
